+func.func @if_regions(%cond: i1, %n: index, %input: tensor<64x64xf32>, %init: tensor<64xf32>) -> tensor<64xf32> {
+  %c0 = arith.constant 0 : index
+  %c1 = arith.constant 1 : index
+  %result = scf.if %cond -> tensor<64xf32> {
